pair A,B,C,D,M,N;
A=(0,0);
B=(1.5,0);
C=(1.5,1);
D=(0,1);
draw (A--B--C--D--A);
M=(0.8,0);
N=(1.2,1);
draw(M--N);
label("M",M,S);
label("N",N,NNE);
[/asy]
